    "items": [
        {
            "chunk_id": "6b5a45f74ff9",
            "decision": "split",
            "confidence": 0.9,
            "knowledge_value": "high",
            "reason": "段落包含华为医疗军团的组织架构、技术基础、目标定位等可沉淀知识，同时涉及OpenAI事件、华为内部调整等动态信息，需分离处理。",
            "knowledge_spans": [
                {
                    "text": "华为DCS领域总裁张伟力将担任华为医疗卫生军团负责人，张伟力此前岗位隶属于华为数据存储产品线",
                    "role": "军团负责人背景",
                    "stability": "high"
                },
                {
                    "text": "华为已正式组建医疗卫生军团，重点构建AI辅助诊断解决方案体系，推动医疗大模型在临床场景的应用",
                    "role": "军团核心目标",
                    "stability": "high"
                },
                {
                    "text": "医疗卫生军团的成立主要是为解决AI在医疗行业落地过程中的技术、生态对接等问题",
                    "role": "军团成立目的",
                    "stability": "high"
                },
                {
                    "text": "医疗军团的方向主要技术基础还是来自于原来的DCS领域，但会从行业角度下沉，加大力度投入医疗领域",
                    "role": "技术来源与行业策略",
                    "stability": "medium"
                },
                {
                    "text": "医疗领域的数据质量很高，这样的行业会率先实现AI应用的落地",
                    "role": "医疗数据特性",
                    "stability": "medium"
                },
                {
                    "text": "从通用大模型到行业场景大模型，需要进行针对性训练，训练所需数据预处理耗时长，收集、清洗等环节占模型开发训练时长60%；行业场景模型训练和应用落地难，项目开发难度大，人员技术要求高，开发周期不可控；因算力等待、任务潮汐、资源碎片化等原因，AI集群可用度往往不足50%",
                    "role": "医疗AI落地挑战",
                    "stability": "high"
                },
                {
                    "text": "瑞智病理大模型RuiPath主要是基于华为DCS AI解决方案，整合了华为内部工具链ModelEngine、DCS XPU池化和容器等技术",
                    "role": "合作案例技术细节",
                    "stability": "medium"
                },
                {
                    "text": "军团模式来自美国互联网公司谷歌，核心是把基础研究的科学家、技术专家、产品专家、工程专家、销售专家、交付与服务专家全都汇聚在一个部门",
                    "role": "军团模式定义",
                    "stability": "high"
                },
                {
                    "text": "华为对军团组织的重新定义，主要是通过军团作战，打破现有组织边界，快速集结资源，穿插作战，提升效率，做深做透一个领域，对商业成功负责",
                    "role": "军团组织原则",
                    "stability": "high"
                },
                {
                    "text": "从2021年开始，华为组建的军团队伍已超过20个，覆盖煤矿、港口、公路、智能光伏以及电力数字化等多个领域，但期间也有推进较慢甚至是关闭的军团，发展成效取决于行业的整体发展",
                    "role": "军团发展概况",
                    "stability": "medium"
                }
            ],
            "event_residue": "OpenAI宣布推出ChatGPT Health(健康)，该模式集成于ChatGPT中，是一个“专门用于与ChatGPT进行健康相关对话的独立空间”，可以连接电子医疗记录和各类健康应用，生成的回复能够结合用户的健康信息与个人情境。OpenAI表示，根据匿名化对话的分析，健康已成为ChatGPT最常见的使用场景之一，全球每周有超过2.3亿人提出与健康和保健相关的问题，凸显医疗健康市场需求的庞大规模。3月8日，记者从多位知情人士确认。不久前有消息称。但华为内部人士对记者表示，目前在相关发文中并没有关于医疗卫生军团职能的具体表述。华为内部人士对记者说。在此前与瑞金医院合作的过程中，华为公司副总裁、数据存储产品线总裁周跃峰曾提及。而当时发布的瑞智病理大模型RuiPath虽然引发华为进军医疗领域的关注。华为内部人士对记者表示，以前华为拥有行业业务部，但范围太大，很难将外部痛点和内部方案进行进行精准匹配，军团解决了这个问题。",
            "drop_target": "event"
        }
    ]
}
